const d = $input.first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;').replace(/'/g, '&#39;');
const held = (d.unmatchedPosts ?? []).map((p) => `<li style="margin:8px 0;"><a href="${esc(p.url)}" style="color:#15140f;">${esc(p.text || p.id)}</a></li>`).join('');
const subject = `trackai — ${d.imported || 0} X test${d.imported === 1 ? '' : 's'} published${d.unmatched ? `, ${d.unmatched} held` : ''}`;
const html = `<!doctype html><html><body style="margin:0;background:#faf9f6;padding:28px 12px;"><div style="max-width:560px;margin:auto;background:#fff;border-radius:14px;padding:26px;font-family:-apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#15140f;"><h1 style="font-size:21px;margin:0 0 10px;">X bookmark import complete</h1><p style="color:#6f6b60;line-height:1.5;">${d.imported || 0} published · ${d.unmatched || 0} newly held · ${d.duplicates || 0} already seen · ${d.scanned || 0} scanned</p>${held ? `<h2 style="font-size:16px;margin-top:24px;">Needs a model match</h2><ul style="padding-left:20px;line-height:1.45;">${held}</ul>` : ''}<p style="margin-top:24px;"><a href="https://trackai.theaugustdispatch.com/admin" style="display:inline-block;background:#e8b73a;color:#1a1710;text-decoration:none;font-weight:700;padding:12px 20px;border-radius:999px;">Open trackai admin</a></p></div></body></html>`;
return [{ json: { subject, html } }];
